window.READING_TESTS[8]={"id": 8, "module": "reading", "vol": 9, "sections": [{"number": 1, "html": "<p class=\"subheading\">Questions 1–7</p><p class=\"instruction\">Choose <b>TRUE</b> if the statement agrees with the information given in the text, choose <b>FALSE</b> if the statement contradicts the information, or choose <b>NOT GIVEN</b> if there is no information on this.</p><div data-render-choice=\"1\"></div><div data-render-choice=\"2\"></div><div data-render-choice=\"3\"></div><div data-render-choice=\"4\"></div><div data-render-choice=\"5\"></div><div data-render-choice=\"6\"></div><div data-render-choice=\"7\"></div>\n<p class=\"subheading\">Questions 8–13</p><p class=\"instruction\">Complete the notes below.</p><p class=\"instruction\">Write <b>ONE WORD ONLY</b> from the passage for each answer.</p><p class=\"\"><b>Challenges faced by RFDS dentists</b></p><p>• need to bring equipment including <span class=\"qnum\">8</span><input class=\"gap\" data-q=\"8\" aria-label=\"Câu 8\" autocomplete=\"off\" spellcheck=\"false\"> for records• aircraft used to carry equipment have restricted <span class=\"qnum\">9</span><input class=\"gap\" data-q=\"9\" aria-label=\"Câu 9\" autocomplete=\"off\" spellcheck=\"false\">• problems offering some services, e.g., fitting <span class=\"qnum\">10</span><input class=\"gap\" data-q=\"10\" aria-label=\"Câu 10\" autocomplete=\"off\" spellcheck=\"false\">• People in remote areas are more likely to have infection in their mouth</p><p class=\"\"><b>Products supplied by RFDS dentists</b></p><p>if necessary RFDS provides:• <span class=\"qnum\">11</span><input class=\"gap\" data-q=\"11\" aria-label=\"Câu 11\" autocomplete=\"off\" spellcheck=\"false\"> and <span class=\"qnum\">12</span><input class=\"gap\" data-q=\"12\" aria-label=\"Câu 12\" autocomplete=\"off\" spellcheck=\"false\"> for regular use• <span class=\"qnum\">13</span><input class=\"gap\" data-q=\"13\" aria-label=\"Câu 13\" autocomplete=\"off\" spellcheck=\"false\"> to limit dental accidents on the sports field. </p>"}, {"number": 2, "html": "<p class=\"subheading\">Questions 14–19</p><p class=\"instruction\">Reading Passage 2 has six paragraphs.</p><p class=\"instruction\">Choose the correct heading for each paragraph from the list of headings below.</p><p class=\"instruction\">Choose the correct number, <b>i-viii</b>, in boxes <b>14-19</b>.</p><p class=\"instruction\"><b>List of headings</b></p><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"i\"><b>i</b> Interpreting the research behind who is participating in art activities</button><button class=\"token\" draggable=\"true\" data-token=\"ii\"><b>ii</b> How sales of artwork have increased in many countries</button><button class=\"token\" draggable=\"true\" data-token=\"iii\"><b>iii</b> Two opportunities for getting kids involved in art activities</button><button class=\"token\" draggable=\"true\" data-token=\"iv\"><b>iv</b> How art can be made accessible to the public</button><button class=\"token\" draggable=\"true\" data-token=\"v\"><b>v</b> Developing a model to explain the lack of participation in art</button><button class=\"token\" draggable=\"true\" data-token=\"vi\"><b>vi</b> The connection between art and media</button><button class=\"token\" draggable=\"true\" data-token=\"vii\"><b>vii</b> How involvement with art affects well-being and attitudes</button><button class=\"token\" draggable=\"true\" data-token=\"viii\"><b>viii</b> How art makes communities safer and more vital</button></div><p class=\"matching-row\" data-drop=\"14\"><span class=\"qnum\">14</span>Paragraph 2 <select class=\"answer-select\" data-q=\"14\" aria-label=\"Câu 14\"><option value=\"\">Chọn</option><option value=\"i\">i · Interpreting the research behind who is participating in art activities</option><option value=\"ii\">ii · How sales of artwork have increased in many countries</option><option value=\"iii\">iii · Two opportunities for getting kids involved in art activities</option><option value=\"iv\">iv · How art can be made accessible to the public</option><option value=\"v\">v · Developing a model to explain the lack of participation in art</option><option value=\"vi\">vi · The connection between art and media</option><option value=\"vii\">vii · How involvement with art affects well-being and attitudes</option><option value=\"viii\">viii · How art makes communities safer and more vital</option></select></p><p class=\"matching-row\" data-drop=\"15\"><span class=\"qnum\">15</span>Paragraph 3 <select class=\"answer-select\" data-q=\"15\" aria-label=\"Câu 15\"><option value=\"\">Chọn</option><option value=\"i\">i · Interpreting the research behind who is participating in art activities</option><option value=\"ii\">ii · How sales of artwork have increased in many countries</option><option value=\"iii\">iii · Two opportunities for getting kids involved in art activities</option><option value=\"iv\">iv · How art can be made accessible to the public</option><option value=\"v\">v · Developing a model to explain the lack of participation in art</option><option value=\"vi\">vi · The connection between art and media</option><option value=\"vii\">vii · How involvement with art affects well-being and attitudes</option><option value=\"viii\">viii · How art makes communities safer and more vital</option></select></p><p class=\"matching-row\" data-drop=\"16\"><span class=\"qnum\">16</span>Paragraph 5 <select class=\"answer-select\" data-q=\"16\" aria-label=\"Câu 16\"><option value=\"\">Chọn</option><option value=\"i\">i · Interpreting the research behind who is participating in art activities</option><option value=\"ii\">ii · How sales of artwork have increased in many countries</option><option value=\"iii\">iii · Two opportunities for getting kids involved in art activities</option><option value=\"iv\">iv · How art can be made accessible to the public</option><option value=\"v\">v · Developing a model to explain the lack of participation in art</option><option value=\"vi\">vi · The connection between art and media</option><option value=\"vii\">vii · How involvement with art affects well-being and attitudes</option><option value=\"viii\">viii · How art makes communities safer and more vital</option></select></p><p class=\"matching-row\" data-drop=\"17\"><span class=\"qnum\">17</span>Paragraph 6 <select class=\"answer-select\" data-q=\"17\" aria-label=\"Câu 17\"><option value=\"\">Chọn</option><option value=\"i\">i · Interpreting the research behind who is participating in art activities</option><option value=\"ii\">ii · How sales of artwork have increased in many countries</option><option value=\"iii\">iii · Two opportunities for getting kids involved in art activities</option><option value=\"iv\">iv · How art can be made accessible to the public</option><option value=\"v\">v · Developing a model to explain the lack of participation in art</option><option value=\"vi\">vi · The connection between art and media</option><option value=\"vii\">vii · How involvement with art affects well-being and attitudes</option><option value=\"viii\">viii · How art makes communities safer and more vital</option></select></p><p class=\"matching-row\" data-drop=\"18\"><span class=\"qnum\">18</span>Paragraph 8 <select class=\"answer-select\" data-q=\"18\" aria-label=\"Câu 18\"><option value=\"\">Chọn</option><option value=\"i\">i · Interpreting the research behind who is participating in art activities</option><option value=\"ii\">ii · How sales of artwork have increased in many countries</option><option value=\"iii\">iii · Two opportunities for getting kids involved in art activities</option><option value=\"iv\">iv · How art can be made accessible to the public</option><option value=\"v\">v · Developing a model to explain the lack of participation in art</option><option value=\"vi\">vi · The connection between art and media</option><option value=\"vii\">vii · How involvement with art affects well-being and attitudes</option><option value=\"viii\">viii · How art makes communities safer and more vital</option></select></p><p class=\"matching-row\" data-drop=\"19\"><span class=\"qnum\">19</span>Paragraph 9 <select class=\"answer-select\" data-q=\"19\" aria-label=\"Câu 19\"><option value=\"\">Chọn</option><option value=\"i\">i · Interpreting the research behind who is participating in art activities</option><option value=\"ii\">ii · How sales of artwork have increased in many countries</option><option value=\"iii\">iii · Two opportunities for getting kids involved in art activities</option><option value=\"iv\">iv · How art can be made accessible to the public</option><option value=\"v\">v · Developing a model to explain the lack of participation in art</option><option value=\"vi\">vi · The connection between art and media</option><option value=\"vii\">vii · How involvement with art affects well-being and attitudes</option><option value=\"viii\">viii · How art makes communities safer and more vital</option></select></p>\n<p class=\"subheading\">Questions 20–23</p><p class=\"instruction\">Look at the following statements (<b>Questions 20-23</b>) and the list of researchers below.</p><p class=\"instruction\">Match each statement with the correct researcher, <b>A-F</b>.</p><p class=\"instruction\"><b>List of Researchers</b></p><p class=\"instruction\"><b>A</b>     Spector </p><p class=\"instruction\"><b>B</b>     Oliphant </p><p class=\"instruction\"><b>C</b>     Riley</p><p class=\"instruction\"><b>D</b>     Hughes</p><p class=\"instruction\"><b>E</b>     Bradshaw</p><p class=\"instruction\"><b>F</b>     Yoshitomi</p><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> Spector</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> Oliphant</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> Riley</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> Hughes</button><button class=\"token\" draggable=\"true\" data-token=\"E\"><b>E</b> Bradshaw</button><button class=\"token\" draggable=\"true\" data-token=\"F\"><b>F</b> Yoshitomi</button></div><p class=\"matching-row\" data-drop=\"20\"><span class=\"qnum\">20</span>Art activities can contribute to lowering negative incidents associated with juvenile crime. <select class=\"answer-select\" data-q=\"20\" aria-label=\"Câu 20\"><option value=\"\">Chọn</option><option value=\"A\">A · Spector</option><option value=\"B\">B · Oliphant</option><option value=\"C\">C · Riley</option><option value=\"D\">D · Hughes</option><option value=\"E\">E · Bradshaw</option><option value=\"F\">F · Yoshitomi</option></select></p><p class=\"matching-row\" data-drop=\"21\"><span class=\"qnum\">21</span>Art can bring money and visitors into a community. <select class=\"answer-select\" data-q=\"21\" aria-label=\"Câu 21\"><option value=\"\">Chọn</option><option value=\"A\">A · Spector</option><option value=\"B\">B · Oliphant</option><option value=\"C\">C · Riley</option><option value=\"D\">D · Hughes</option><option value=\"E\">E · Bradshaw</option><option value=\"F\">F · Yoshitomi</option></select></p><p class=\"matching-row\" data-drop=\"22\"><span class=\"qnum\">22</span>Commercial interests are drawn to areas that emphasize public art. <select class=\"answer-select\" data-q=\"22\" aria-label=\"Câu 22\"><option value=\"\">Chọn</option><option value=\"A\">A · Spector</option><option value=\"B\">B · Oliphant</option><option value=\"C\">C · Riley</option><option value=\"D\">D · Hughes</option><option value=\"E\">E · Bradshaw</option><option value=\"F\">F · Yoshitomi</option></select></p><p class=\"matching-row\" data-drop=\"23\"><span class=\"qnum\">23</span>Art activities can both energize and calm people. <select class=\"answer-select\" data-q=\"23\" aria-label=\"Câu 23\"><option value=\"\">Chọn</option><option value=\"A\">A · Spector</option><option value=\"B\">B · Oliphant</option><option value=\"C\">C · Riley</option><option value=\"D\">D · Hughes</option><option value=\"E\">E · Bradshaw</option><option value=\"F\">F · Yoshitomi</option></select></p>\n<p class=\"subheading\">Questions 24–26</p><p class=\"instruction\">Complete the sentences below.</p><p class=\"instruction\">Write <b>ONE WORD ONLY</b> from the passage for each answer.</p><p>Sometimes people want to get involved in art activities but can&#x27;t afford it, can&#x27;t fit it into their schedule, or don&#x27;t have the suitable <span class=\"qnum\">24</span><input class=\"gap\" data-q=\"24\" aria-label=\"Câu 24\" autocomplete=\"off\" spellcheck=\"false\"></p><p>A noticeable correlation exists between art involvement in childhood and those in adulthood <span class=\"qnum\">25</span><input class=\"gap\" data-q=\"25\" aria-label=\"Câu 25\" autocomplete=\"off\" spellcheck=\"false\"></p><p>The National Photography Program allows members to grow personally and also gain <span class=\"qnum\">26</span><input class=\"gap\" data-q=\"26\" aria-label=\"Câu 26\" autocomplete=\"off\" spellcheck=\"false\"> for their artistic achievements.</p>"}, {"number": 3, "html": "<p class=\"subheading\">Questions 27–31</p><p class=\"instruction\">Choose <b>YES</b> if the statement agrees with the claims of the writer, choose <b>NO</b> if the statement contradicts the claims of the writer, or <b>NOT GIVEN</b> if it is impossible to say what the writer thinks about this.</p><div data-render-choice=\"27\"></div><div data-render-choice=\"28\"></div><div data-render-choice=\"29\"></div><div data-render-choice=\"30\"></div><div data-render-choice=\"31\"></div>\n<p class=\"subheading\">Questions 32–36</p><p class=\"instruction\">Choose the correct answer.</p><div data-render-choice=\"32\"></div><div data-render-choice=\"33\"></div><div data-render-choice=\"34\"></div><div data-render-choice=\"35\"></div><div data-render-choice=\"36\"></div>\n<p class=\"subheading\">Questions 37–40</p><p class=\"instruction\">Complete each sentence with the correct ending, <b>A-F</b>, below.</p><p class=\"\"><b>A </b>reflects the mood created by the natural environment.<b>B </b>demonstrates that the dominant art form in Australia is landscape painting.<b>C</b> demonstrates an understanding of the historical importance of the land.<b>D</b> showcases a very small number of artists.<b>E</b> demonstrates a strong European flavour.<b>F</b>shows an acceptance of the unique qualities of Australian art.</p><p>In spite of its conservatism, the Royal Academy exhibition <span class=\"inline-match\" data-drop=\"37\"><span class=\"qnum\">37</span><select class=\"answer-select\" data-q=\"37\" aria-label=\"Câu 37\"><option value=\"\">Chọn</option><option value=\"A\">A · reflects the mood created by the natural environment.</option><option value=\"B\">B · demonstrates that the dominant art form in Australia is landscape painting.</option><option value=\"C\">C · demonstrates an understanding of the historical importance of the land.</option><option value=\"D\">D · showcases a very small number of artists.</option><option value=\"E\">E · demonstrates a strong European flavour.</option><option value=\"F\">F · shows an acceptance of the unique qualities of Australian art.</option></select></span>Australian art of the early to mid-1800s <span class=\"inline-match\" data-drop=\"38\"><span class=\"qnum\">38</span><select class=\"answer-select\" data-q=\"38\" aria-label=\"Câu 38\"><option value=\"\">Chọn</option><option value=\"A\">A · reflects the mood created by the natural environment.</option><option value=\"B\">B · demonstrates that the dominant art form in Australia is landscape painting.</option><option value=\"C\">C · demonstrates an understanding of the historical importance of the land.</option><option value=\"D\">D · showcases a very small number of artists.</option><option value=\"E\">E · demonstrates a strong European flavour.</option><option value=\"F\">F · shows an acceptance of the unique qualities of Australian art.</option></select></span>The modern work by Gladwell chosen for the exhibition <span class=\"inline-match\" data-drop=\"39\"><span class=\"qnum\">39</span><select class=\"answer-select\" data-q=\"39\" aria-label=\"Câu 39\"><option value=\"\">Chọn</option><option value=\"A\">A · reflects the mood created by the natural environment.</option><option value=\"B\">B · demonstrates that the dominant art form in Australia is landscape painting.</option><option value=\"C\">C · demonstrates an understanding of the historical importance of the land.</option><option value=\"D\">D · showcases a very small number of artists.</option><option value=\"E\">E · demonstrates a strong European flavour.</option><option value=\"F\">F · shows an acceptance of the unique qualities of Australian art.</option></select></span>Including Aboriginal art in the exhibition <span class=\"inline-match\" data-drop=\"40\"><span class=\"qnum\">40</span><select class=\"answer-select\" data-q=\"40\" aria-label=\"Câu 40\"><option value=\"\">Chọn</option><option value=\"A\">A · reflects the mood created by the natural environment.</option><option value=\"B\">B · demonstrates that the dominant art form in Australia is landscape painting.</option><option value=\"C\">C · demonstrates an understanding of the historical importance of the land.</option><option value=\"D\">D · showcases a very small number of artists.</option><option value=\"E\">E · demonstrates a strong European flavour.</option><option value=\"F\">F · shows an acceptance of the unique qualities of Australian art.</option></select></span></p>"}], "passages": [{"number": 1, "title": "Australia's Airborne Dentists", "subtitle": ""}, {"number": 2, "title": "Public art programs: research update", "subtitle": ""}, {"number": 3, "title": "200 Years of Australian Landscapes at the Royal Academy in London", "subtitle": "<i>This exhibition promises to chart the evolution of a nation through its art, but not everyone agrees with the reasons behind the choice of artwork</i>"}], "singles": [{"n": 1, "prompt": "Many of the RFDS doctors work as volunteers.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 2, "prompt": "RFDS dentists make trips to outback communities each month.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 3, "prompt": "RFDS dentists are accompanied on their journeys to remote areas by a dental nurse.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 4, "prompt": "RFDS dentists must provide a wide range of dental services.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 5, "prompt": "Rural dental patients are more informed about oral hygiene than urban patients", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 6, "prompt": "RFDS dentists educate patients about good eating habits.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 7, "prompt": "Urban Australians generally have better teeth because their water is treated.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 27, "prompt": "As expected, the artworks chosen for the exhibition reflect a narrow interpretation of landscape.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 28, "prompt": "The Academy rejected Australian suggestions for the subject of the exhibition.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 29, "prompt": "The colonial relationship meant that early Australian landscape painting followed the traditions of English landscape painting.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 30, "prompt": "The exhibition reflects the fact that Australian art developed its own particular qualities.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 31, "prompt": "Contemporary Australian artists have generally rejected British landscape traditions.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 32, "prompt": "What is the writer’s main point in the second paragraph?", "options": ["Australian landscape painting derives from the British tradition.", "Australian landscape painting is more highly regarded than British.", "Britain is still imposing its principles on Australian art.", "British art cannot be compared to Australian art."]}, {"n": 33, "prompt": "What does Joanna Mendelssohn find surprising?", "options": ["Modern Australian landscape painting has great variety.", "The guidelines for the choice of work were very traditional.", "Landscape painting remains a popular subject for British artists.", "The British find the Australian landscape unsuitable as a subject."]}, {"n": 34, "prompt": "Shaun Gladwell’s work is included in the exhibition because", "options": ["it adopts a subjective approach to depicting the landscape.", "skateboarding is an inspiration to many Australian artists.", "storms are a significant feature in the Australian landscape.", "Bondi is an iconic Australian location."]}, {"n": 35, "prompt": "What was the reason for Soriano including Aboriginal art in the exhibition?", "options": ["It is not well known in London art circles.", "Aboriginal landscape painting influenced Australian settlers.", "It is part of the Australian art tradition and not independent of it.", "Modern Aboriginal painting deals with changes to the landscape."]}, {"n": 36, "prompt": "By referring to China, Mendelssohn is making the point that", "options": ["having an exhibition in London is not as important as it used to be.", "young artists in Britain are not interested in Australian art.", "art from Shanghai is more important than Australian art.", "New York is still a preferred destination for young artists."]}], "pairs": [], "answers": {"1": ["NOT GIVEN"], "2": ["FALSE"], "3": ["NOT GIVEN"], "4": ["TRUE"], "5": ["FALSE"], "6": ["NOT GIVEN"], "7": ["TRUE"], "8": ["computers"], "9": ["space"], "10": ["dentures"], "11": ["toothpaste"], "12": ["toothbrushes"], "13": ["mouthguards"], "14": ["vii"], "15": ["viii"], "16": ["iv"], "17": ["v"], "18": ["i"], "19": ["iii"], "20": ["A"], "21": ["D"], "22": ["C"], "23": ["B"], "24": ["attire"], "25": ["rates"], "26": ["recognition"], "27": ["NO"], "28": ["NOT GIVEN"], "29": ["YES"], "30": ["YES"], "31": ["NO"], "32": ["C"], "33": ["B"], "34": ["A"], "35": ["C"], "36": ["A"], "37": ["F"], "38": ["E"], "39": ["A"], "40": ["C"]}, "explanations": {"1": "<p>1. NOT GIVEN</p><p>Câu hỏi: <i>Many of the RFDS doctors work as volunteers.</i></p><p>(Nhiều bác sĩ của RFDS làm việc với tư cách tình nguyện viên.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Organisations such as the Royal Flying Doctor Service (RFDS) have been established to bring health services to outback Australian communities. The RFDS provides free medical care to people who live, work or travel in remote and regional parts of Australia. This non-profit organisation is the oldest and largest airborne health service of its kind in the world</p><p>(Các tổ chức như Dịch vụ Bác sĩ Bay Hoàng gia (RFDS) được thành lập để mang dịch vụ y tế đến các cộng đồng vùng sâu vùng xa của Úc. RFDS cung cấp dịch vụ chăm sóc y tế miễn phí cho những người sống, làm việc hoặc đi lại ở các vùng xa xôi và nông thôn của Úc. Tổ chức phi lợi nhuận này là dịch vụ y tế trên không lâu đời nhất và lớn nhất thuộc loại hình này trên thế giới.)</p><p>Giải thích: Bài nói tổ chức phi lợi nhuận khám chữa miễn phí nhưng không nói bác sĩ có phải tình nguyện viên không</p>", "2": "<p>2 FALSE</p><p>Câu hỏi: <i>RFDS dentists make trips to outback communities each month.</i></p><p>(Các nha sĩ RFDS đến cộng đồng vùng hẻo lánh mỗi tháng.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>:  RFDS dentists might only visit a community once every few months, or sometimes once per year.</p><p>(Các nha sĩ của RFDS có thể chỉ đến thăm một cộng đồng vài tháng một lần, hoặc đôi khi chỉ một lần mỗi năm.)</p>", "3": "<p>3 NOT GIVEN</p><p>Câu hỏi: <i>RFDS dentists are accompanied on their journeys to remote areas by a dental nurse.</i></p><p>(Nha sĩ RFDS được y tá nha khoa đi cùng khi tới vùng xa. )</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: In some locations that the RFDS visits, there are no suitable dental facilities, so dentists have to bring everything with them.</p><p>(Ở một số địa điểm mà RFDS đến thăm, không có cơ sở nha khoa phù hợp, vì vậy các nha sĩ phải mang theo mọi thứ cần thiết.)</p><p>Giải thích: Không có thông tin về y tá nha khoa hay người đi cùng</p>", "4": "<p>4 TRUE</p><p>Câu hỏi: <i>RFDS dentists must provide a wide range of dental services.</i></p><p>(Nha sĩ RFDS phải cung cấp nhiều loại dịch vụ nha khoa.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: They need to be able to do all kinds of dental procedures, as they don&#x27;t have the ability to refer patients to more specialised dentists.</p><p>(Họ cần có khả năng thực hiện tất cả các loại thủ thuật nha khoa, vì họ không có khả năng giới thiệu bệnh nhân đến các nha sĩ chuyên khoa hơn.)</p>", "5": "<p>5 FALSE</p><p>Câu hỏi: <i>Rural dental patients are more informed about oral hygiene than urban patients.</i></p><p>(Bệnh nhân vùng quê hiểu biết về vệ sinh răng miệng hơn người ở thành phố.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Because there aren&#x27;t a lot of dental services in remote areas, people living in these areas also receive less education about good dental hygiene than their city counterparts do.</p><p>(Do các dịch vụ nha khoa ở vùng sâu vùng xa không nhiều, người dân sống ở những khu vực này cũng nhận được ít kiến thức về vệ sinh răng miệng tốt hơn so với người dân thành phố.)</p>", "6": "<p>6 NOT GIVEN</p><p>Câu hỏi: <i>RFDS dentists educate patients about good eating habits.</i></p><p>(Nha sĩ RFDS dạy bệnh nhân về thói quen ăn uống tốt.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: RFDS dentists try to focus on preventative oral health and educate their patients on good oral hygiene, such as tooth brushing and flossing.</p><p>(Các nha sĩ thuộc RFDS cố gắng tập trung vào chăm sóc sức khỏe răng miệng phòng ngừa và giáo dục bệnh nhân về vệ sinh răng miệng tốt, chẳng hạn như đánh răng và dùng chỉ nha khoa.)</p><p>Giải thích: Đoạn văn chỉ nói về việc các nha sỹ giáo dục bệnh nhân chăm sóc răng miệng nhưng không nói là họ có giáo dục về thói quen ăn uống hay không, điều này không xác định được trong bài</p>", "7": "<p>7 TRUE</p><p>Câu hỏi: <i>Urban Australians generally have better teeth because their water is treated.</i></p><p>(Người Úc ở thành phố nhìn chung có răng khỏe hơn vì nước được xử lý fluoride.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: City dwellers in Australia use water supplies that have been fluoridated, and their rates of tooth decay are lower because of this.</p><p>(Người dân thành thị ở Úc sử dụng nguồn nước có chứa fluoride, và do đó tỷ lệ sâu răng của họ thấp hơn.)</p>", "8": "<p>8 computers</p><p>Câu hỏi: <i>need to bring equipment including  ______ for records</i></p><p>( cần mang theo thiết bị, bao gồm ______ để lưu hồ sơ)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: This includes drills, dentists&#x27; chairs, portable X-ray machines, and computers for keeping track of patients&#x27; treatments.</p><p>(Điều này bao gồm máy khoan, ghế nha khoa, máy chụp X-quang di động và máy tính để theo dõi quá trình điều trị của bệnh nhân.)</p>", "9": "<p>9 space</p><p>Câu hỏi: <i>aircraft used to carry equipment have restricted ______</i></p><p>( máy bay dùng để chở thiết bị bị hạn chế về  ______)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Equipment can weigh up to 100 kilograms, and since the small planes that transport dentists have limited space, dentists cannot always bring everything that they need.</p><p>(Thiết bị có thể nặng tới 100kg, và vì những chiếc máy bay nhỏ chuyên chở nha sĩ có không gian hạn chế, nên nha sĩ không phải lúc nào cũng mang theo tất cả những thứ họ cần.)</p>", "10": "<p>10 dentures</p><p>Câu hỏi: <i>problems offering some services, e.g. fitting ______</i></p><p>(gặp khó khăn khi cung cấp một số dịch vụ, ví dụ như lắp  ______)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: For example, dentures (artificial teeth) can be very difficult to provide, as they need to be the right shape and size for the patient, and this requires many visits over a long period of time.</p><p>(Ví dụ, việc làm răng giả có thể rất khó khăn, vì chúng cần phải có hình dạng và kích thước phù hợp với bệnh nhân, và điều này đòi hỏi nhiều lần đến khám trong một thời gian dài.)</p>", "11": "<p>11 toothpaste</p><p>Câu hỏi: if necessary RFDS provides:</p><p>11 ______ and 12 ______ for regular use</p><p>(nếu cần thiết, RFDS cung cấp:</p><p>11 ______ và 12 ______ để sử dụng thường xuyên)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Also, basic dental hygiene items such as toothpaste and toothbrushes can be more expensive in outback areas. Many people are on low incomes, meaning they have extra difficulty affording these products.</p><p>(Ngoài ra, các vật dụng vệ sinh răng miệng cơ bản như kem đánh răng và bàn chải đánh răng cũng có thể đắt hơn ở các vùng hẻo lánh. Nhiều người có thu nhập thấp, điều đó có nghĩa là họ gặp khó khăn hơn trong việc mua những sản phẩm này.)</p>", "12": "<p>12 toothbrushes</p><p>Câu hỏi: <i>if necessary RFDS provides:</i></p><p><i>11 ______ and 12 ______ for regular use</i></p><p>(nếu cần thiết, RFDS cung cấp:</p><p>11 ______ và 12 ______ để sử dụng thường xuyên)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Also, basic dental hygiene items such as toothpaste and toothbrushes can be more expensive in outback areas. Many people are on low incomes, meaning they have extra difficulty affording these products.</p><p>(Ngoài ra, các vật dụng vệ sinh răng miệng cơ bản như kem đánh răng và bàn chải đánh răng cũng có thể đắt hơn ở các vùng hẻo lánh. Nhiều người có thu nhập thấp, điều đó có nghĩa là họ gặp khó khăn hơn trong việc mua những sản phẩm này.)</p>", "13": "<p>13 mouthguards</p><p>Câu hỏi: <i>______ to limit dental accidents on the sports field</i></p><p>( ______ để hạn chế tai nạn/chấn thương răng miệng trên sân thể thao)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: The RFDS also provides mouthguards for young sports players.</p><p>(RFDS cũng cung cấp dụng cụ bảo vệ răng miệng cho các vận động viên trẻ.)</p>", "14": "<p>14 vii How involvement with art affects well-being and attitudes</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Both active and passive art experiences can provide the benefits of discovery, stimulation and relaxation (Oliphant 2000). Furthermore, people&#x27;s participation in art enhances their development and expands their thoughts about culture.In short, art can make individuals more socially conscious.</p><p>(Cả trải nghiệm nghệ thuật chủ động và thụ động đều có thể mang lại lợi ích khám phá, kích thích và thư giãn (Oliphant 2000). Hơn nữa, sự tham gia của con người vào nghệ thuật thúc đẩy sự phát triển và mở rộng tầm nhìn về văn hóa. Tóm lại, nghệ thuật có thể giúp cá nhân nâng cao nhận thức xã hội.)</p><p>=&gt; Đáp án: vii. How involvement with art affects well-being and attitudes (Việc tham gia nghệ thuật ảnh hưởng thế nào đến đời sống tinh thần và thái độ)</p>", "15": "<p>15 viii How art makes communities safer and more vital</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Revitalization efforts have increased in many cities because of the strong presence of art opportunities.</p><p>Art programs can be highly effective in reducing community problems related to delinquent behavior and truancy in youth (Spector 2000).</p><p>(Nỗ lực hồi sinh đã gia tăng ở nhiều thành phố do sự hiện diện mạnh mẽ của các cơ hội nghệ thuật.</p><p>Các chương trình nghệ thuật có thể rất hiệu quả trong việc giảm thiểu các vấn đề cộng đồng liên quan đến hành vi phạm pháp và bỏ học ở thanh thiếu niên (Spector 2000))</p><p>=&gt; Đáp án: viii. How art makes communities safer and more vital (Nghệ thuật giúp cộng đồng an toàn và phát triển hơn như thế nào)</p>", "16": "<p>16 iv How art can be made accessible to the public</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Public art works can include street furniture, decorations, paving and landmarks, and may take on many forms, including sculpture, decorative ironwork, mosaic flooring and murals. The primary purpose of public art is to bring art into everyday life, to energize public spaces and to arouse society&#x27;s thinking and imagination.</p><p>(Các tác phẩm nghệ thuật công cộng có thể bao gồm đồ nội thất đường phố, đồ trang trí, vỉa hè và các công trình kiến trúc nổi bật, và có thể mang nhiều hình thức khác nhau, bao gồm điêu khắc, đồ sắt trang trí, sàn khảm và tranh tường. Mục đích chính của nghệ thuật công cộng là đưa nghệ thuật vào cuộc sống thường nhật, làm sống động không gian công cộng và khơi gợi tư duy và trí tưởng tượng của xã hội.)</p><p>=&gt; Đáp án: iv. How art can be made accessible to the public ( Cách đưa nghệ thuật đến gần công chúng)</p>", "17": "<p>17 v Developing a model to explain the lack of participation in art</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: To help researchers shed light on this question, the RAND Corporation, a nonprofit institution that helps improve policy and decision-making through objective research and analysis, developed &quot;A Behavior Model of the Participant Decision&quot;, which can be used to investigate people&#x27;s inclinations about participating in an art activity (Yoshitomi 2000).</p><p>(Để giúp các nhà nghiên cứu làm sáng tỏ câu hỏi này, Tập đoàn RAND, một tổ chức phi lợi nhuận giúp cải thiện chính sách và việc ra quyết định thông qua nghiên cứu và phân tích khách quan, đã phát triển &quot;Mô hình hành vi quyết định của người tham gia&quot;, có thể được sử dụng để điều tra khuynh hướng của mọi người về việc tham gia vào một hoạt động nghệ thuật (Yoshitomi 2000).)</p><p>=&gt; Đáp án: v. Developing a model to explain the lack of participation in art (Xây dựng mô hình để giải thích sự thiếu tham gia vào nghệ thuật.)</p>", "18": "<p>18 i Interpreting the research behind who is participating in art activities</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Researchers suggest that a strong relationship exists between childhood and adult art participation rates. Individuals with a greater number of childhood art experiences are more likely to have higher rates of participation as adults. Although 90 percent of Americans believe art instruction is important for children and should be offered in schools, almost 40 percent of schools either offer no art instruction or have art instructors with no formal art training.</p><p>(Các nhà nghiên cứu cho rằng có mối quan hệ mật thiết giữa tỷ lệ tham gia nghệ thuật thời thơ ấu và khi trưởng thành. Những người có nhiều trải nghiệm nghệ thuật thời thơ ấu hơn có nhiều khả năng tham gia nghệ thuật nhiều hơn khi trưởng thành. Mặc dù 90% người Mỹ tin rằng việc dạy nghệ thuật rất quan trọng đối với trẻ em và nên được đưa vào chương trình học ở trường, nhưng gần 40% trường học hoặc không dạy nghệ thuật hoặc có giáo viên dạy nghệ thuật không được đào tạo bài bản về nghệ thuật.)</p><p>=&gt; Đáp án: i. Interpreting the research behind who is participating in art activities (Phân tích nghiên cứu về những người tham gia các hoạt động nghệ thuật)</p>", "19": "<p>19 iii Two opportunities for getting kids involved in art activities</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: One recreation organization working to make sure children get exposed to art is the Boys and Girls Clubs of America, which offer two innovative programs: The National Photography Program and the National Fine Arts Exhibit.</p><p>(Một tổ chức giải trí đang nỗ lực đảm bảo trẻ em được tiếp xúc với nghệ thuật là Câu lạc bộ Thiếu niên và Thiếu nữ Hoa Kỳ, tổ chức này cung cấp hai chương trình sáng tạo: Chương trình Nhiếp ảnh Quốc gia và Triển lãm Mỹ thuật Quốc gia.)</p><p>=&gt; Đáp án: iii. Two opportunities for getting kids involved in art activities (Hai cơ hộ giúp trẻ em tham gia hoạt động nghệ thuật)</p>", "20": "<p>20 A</p><p>Câu hỏi: <i>Art activities can contribute to lowering negative incidents associated with juvenile crime.</i></p><p>(Hoạt động nghệ thuật có thể góp phần làm giảm các vấn đề tiêu cực liên quan đến tội phạm vị thành niên.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Art programs can be highly effective in reducing community problems related to delinquent behavior and truancy in youth (Spector 2000).</p><p>(Các chương trình nghệ thuật có thể rất hiệu quả trong việc giảm thiểu các vấn đề cộng đồng liên quan đến hành vi phạm pháp và bỏ học ở thanh thiếu niên (Spector 2000))</p><p>=&gt; Đáp án: A Spector</p>", "21": "<p>21 D</p><p>Câu hỏi: <i>Art can bring money and visitors into a community.</i></p><p>(Nghệ thuật có thể mang tiền bạc và khách đến cho cộng đồng.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Art-related tourism generates tourists and revenue, attracts high-income consumers, extends the tourist season and is a &quot;green&quot; form of the industry (Hughes 2000).</p><p>(Du lịch liên quan đến nghệ thuật tạo ra khách du lịch và doanh thu, thu hút người tiêu dùng có thu nhập cao, kéo dài mùa du lịch và là một hình thức &quot;xanh&quot; của ngành công nghiệp này (Hughes 2000).)</p><p>=&gt; Đáp án: D Hughes</p>", "22": "<p>22 C</p><p>Câu hỏi: <i>Commercial interests are drawn to areas that emphasize public art.</i></p><p>(Các lợi ích thương mại bị thu hút tới những nơi chú trọng nghệ thuật công cộng.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Communities committed to providing opportunities for experiencing art are considered more livable because they are attractive to businesses and industry and they offer a higher quality of life for residents (Riley 2002).</p><p>(Các cộng đồng cam kết tạo cơ hội trải nghiệm nghệ thuật được coi là đáng sống hơn vì chúng thu hút các doanh nghiệp và ngành công nghiệp, đồng thời mang lại chất lượng cuộc sống cao hơn cho cư dân (Riley 2002).)</p><p>=&gt; Đáp án: C Riley</p>", "23": "<p>23 B</p><p>Câu hỏi: <i>Art activities can both energize and calm people.</i></p><p>(Hoạt động nghệ thuật có thể vừa tạo năng lượng vừa giúp con người thư giãn.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Both active and passive art experiences can provide the benefits of discovery, stimulation and relaxation (Oliphant 2000). Furthermore, people&#x27;s participation in art enhances their development and expands their thoughts about culture.In short, art can make individuals more socially conscious.</p><p>(Cả trải nghiệm nghệ thuật chủ động và thụ động đều có thể mang lại lợi ích khám phá, kích thích và thư giãn (Oliphant 2000). Hơn nữa, sự tham gia của con người vào nghệ thuật thúc đẩy sự phát triển và mở rộng tầm nhìn về văn hóa. Tóm lại, nghệ thuật có thể giúp cá nhân nâng cao nhận thức xã hội.)</p><p>=&gt; Đáp án: B Oliphant</p>", "24": "<p>24 attire</p><p>Câu hỏi: <i>Sometimes people want to get involved in art activities but can&#x27;t afford it, can&#x27;t fit it into their schedule, or don&#x27;t have the suitable ______.</i></p><p>(Đôi khi mọi người muốn tham gia hoạt động nghệ thuật nhưng không đủ khả năng chi trả, không sắp xếp được thời gian, hoặc không có ______ phù hợp.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: The inclined are interested in participating, but may be constrained by particular barriers such as cost, time, and proper attire.</p><p>(Những người có hứng thú đều muốn tham gia, nhưng có thể bị cản trở bởi một số yếu tố nhất định như chi phí, thời gian và trang phục phù hợp.)</p>", "25": "<p>25 rates</p><p>Câu hỏi: <i>A noticeable correlation exists between art involvement in childhood and those in adulthood ______.</i></p><p>(Có một mối liên hệ rõ rệt giữa việc tham gia nghệ thuật khi còn nhỏ và khi trưởng thành ______.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Researchers suggest that a strong relationship exists between childhood and adult art participation rates.</p><p>(Các nhà nghiên cứu cho rằng có mối quan hệ mật thiết giữa tỷ lệ tham gia nghệ thuật thời thơ ấu và khi trưởng thành.)</p>", "26": "<p>26 recognition</p><p>Câu hỏi: <i>The National Photography Program allows members to grow personally and also gain ______ for their artistic achievements.</i></p><p>(Chương trình Nhiếp ảnh Quốc gia cho phép các thành viên phát triển bản thân và đồng thời nhận được ______ cho thành tựu nghệ thuật của họ.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: The program provides club members with the opportunity to achieve personal growth and receive artistic recognition through instruction in photography.</p><p>(Chương trình này mang đến cho các thành viên câu lạc bộ cơ hội phát triển bản thân và nhận được sự công nhận về mặt nghệ thuật thông qua việc học nhiếp ảnh.)</p>", "27": "<p>27 NO</p><p>Câu hỏi: <i>As expected, the artworks chosen for the exhibition reflect a narrow interpretation of landscape.</i></p><p>(Như dự đoán, các tác phẩm được chọn cho triển lãm phản ánh một cách hiểu hẹp về tranh phong cảnh.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: It is hardly surprising, then, that this results in a flexible, wide-ranging notion of landscape.</p><p>(Vì vậy, việc điều này dẫn đến một khái niệm linh hoạt và rất rộng về tranh phong cảnh là điều không có gì đáng ngạc nhiên. )</p>", "28": "<p>28 NOT GIVEN</p><p>Câu hỏi: <i>The Academy rejected Australian suggestions for the subject of the exhibition.</i></p><p>(Học viện Hoàng gia đã bác bỏ những đề xuất từ phía Úc về chủ đề của triển lãm.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: British artistic values have directed this exhibition, rather than allowing Australia the freedom to demonstrate its maturity.</p><p>(Những giá trị nghệ thuật của Anh đã định hướng triển lãm này, thay vì để nước Úc tự do thể hiện sự trưởng thành của nền nghệ thuật của mình.)</p><p>Giải thích: Bài chỉ nói ảnh hưởng của quan điểm nghệ thuật Anh, không có chỗ nào nói Úc đưa đề xuất rồi bị từ chối → thiếu thông tin</p>", "29": "<p>29 YES</p><p>Câu hỏi: <i>The colonial relationship meant that early Australian landscape painting followed the traditions of English landscape painting.</i></p><p>(Mối quan hệ thuộc địa khiến tranh phong cảnh Úc thời kỳ đầu đi theo truyền thống tranh phong cảnh Anh.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Because of colonial ties, it was inevitable during Australian art’s formative years that it would reflect Britain’s devotion to the beloved landscape before its own character and idiosyncrasies took shape.</p><p>(Do mối liên hệ thuộc địa, trong giai đoạn hình thành của nghệ thuật Úc, việc nó phản ánh niềm yêu thích của Anh đối với tranh phong cảnh là điều không thể tránh khỏi, trước khi nghệ thuật Úc phát triển bản sắc và những nét riêng của mình.)</p>", "30": "<p>30 YES</p><p>Câu hỏi:<i> The exhibition reflects the fact that Australian art developed its own particular qualities.</i></p><p>(Triển lãm phản ánh việc nghệ thuật Úc đã phát triển những nét riêng của mình.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: ‘What I wanted to show was how Australian art develops a real distinctiveness, associated with the landscape and the light.’</p><p>(“Điều tôi muốn thể hiện là nghệ thuật Úc đã phát triển một bản sắc thật sự riêng biệt, gắn liền với cảnh quan và ánh sáng.”)</p>", "31": "<p>31 NO</p><p>Câu hỏi: <i>Contemporary Australian artists have generally rejected British landscape traditions.</i></p><p>(Các nghệ sĩ Úc đương đại nhìn chung đã từ bỏ truyền thống tranh phong cảnh Anh.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: British landscape painting is still relevant to a current generation of Australian practitioners, however indirectly.</p><p>(Tranh phong cảnh Anh vẫn còn ảnh hưởng đến thế hệ họa sĩ Úc hiện nay, dù là gián tiếp.)</p>", "32": "<p>32 C</p><p>Câu hỏi: <i>What is the writer’s main point in the second paragraph?</i>A.    Australian landscape painting derives from the British tradition.B.    Australian landscape painting is more highly regarded than British.C.    Britain is still imposing its principles on Australian art.D.    British art cannot be compared to Australian art.</p><p>(<i>Ý chính của đoạn 2 là gì?</i>A.    Tranh phong cảnh Úc bắt nguồn từ truyền thống Anh.B.    Tranh phong cảnh Úc được đánh giá cao hơn tranh Anh.C.    Anh vẫn đang áp đặt quan điểm nghệ thuật của mình lên nghệ thuật Úc.D.    Không thể so sánh nghệ thuật Anh với nghệ thuật Úc.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: There is a suggestion that British artistic values have directed this exhibition, rather than allowing Australia the freedom to demonstrate its maturity.</p><p>(Có ý kiến cho rằng chính các giá trị nghệ thuật của Anh đã định hướng triển lãm này, thay vì cho Úc tự do thể hiện sự trưởng thành của mình.)</p>", "33": "<p>33 B</p><p>Câu hỏi: <i>What does Joanna Mendelssohn find surprising?</i>A.    Modern Australian landscape painting has great variety.B.    The guidelines for the choice of work were very traditional.C.    Landscape painting remains a popular subject for British artists.D.    The British find the Australian landscape unsuitable as a subject.</p><p>(<i>Joanna Mendelssohn ngạc nhiên vì điều gì?</i>A.    Tranh phong cảnh Úc hiện đại rất đa dạng.B.    Các tiêu chí chọn tác phẩm rất truyền thống/bảo thủ.C.    Tranh phong cảnh vẫn là chủ đề phổ biến với nghệ sĩ Anh.D.    Người Anh cho rằng phong cảnh Úc không phù hợp làm đề tài.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: What Mendelssohn found surprising about the exhibition was that the underlying rules for the selection of works seemed to have been so conservative.</p><p>(Điều khiến Mendelssohn ngạc nhiên về triển lãm là những quy tắc cơ bản trong việc lựa chọn tác phẩm dường như quá bảo thủ.)</p>", "34": "<p>34 A</p><p>Câu hỏi: (<i>Shaun Gladwell’s work is included in the exhibition because</i>A.    it adopts a subjective approach to depicting the landscape.B.    skateboarding is an inspiration to many Australian artists.C.    storms are a significant feature in the Australian landscape.D.    Bondi is an iconic Australian location.)</p><p>(<i>Tác phẩm của Shaun Gladwell được đưa vào triển lãm vì</i>A.    nó thể hiện phong cảnh theo góc nhìn cá nhân/chủ quan.B.    trượt ván là nguồn cảm hứng cho nhiều nghệ sĩ Úc.C.    bão là đặc điểm nổi bật của phong cảnh Úc.D.    Bondi là địa điểm biểu tượng của Úc.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: It is his acknowledgment of landscape (or seascape) tradition, coloured by Gladwell’s own individualism. ‘To exhibit my work in this show might make some sense because I was interested in Turner and the idea of atmosphere affecting vision, something I was really interested in around the time of Storm Sequence. I was thinking about this tradition of Romantic landscape, but I wanted to make it personal,’ says Gladwell.</p><p>(Đó là sự thừa nhận của ông về truyền thống tranh phong cảnh (hoặc tranh biển), được tô điểm bởi cá tính riêng của Gladwell. “Việc trưng bày tác phẩm của tôi trong triển lãm này có lẽ có ý nghĩa vì tôi quan tâm đến Turner và ý tưởng về bầu không khí ảnh hưởng đến thị giác, điều mà tôi thực sự quan tâm vào khoảng thời gian thực hiện loạt tranh ‘Chuỗi Bão’. Tôi đã suy nghĩ về truyền thống tranh phong cảnh lãng mạn này, nhưng tôi muốn biến nó thành của riêng mình,” Gladwell nói.)</p>", "35": "<p>35 C</p><p>Câu hỏi: <i>What was the reason for Soriano including Aboriginal art in the exhibition?</i>A.    It is not well known in London art circles.B.    Aboriginal landscape painting influenced Australian settlers.C.    It is part of the Australian art tradition and not independent of it.D.    Modern Aboriginal painting deals with changes to the landscape.</p><p>(<i>Vì sao Soriano đưa nghệ thuật Aboriginal vào triển lãm?</i>A.    Vì giới nghệ thuật London chưa biết nhiều về nó.B.    Vì tranh phong cảnh Aboriginal ảnh hưởng đến người định cư Úc.C.    Vì nó là một phần của truyền thống nghệ thuật Úc chứ không tách riêng.D.    Vì tranh Aboriginal hiện đại nói về những thay đổi của cảnh quan.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: [The exhibition] is a beautiful meshing of the two different kinds of art that allowed me to bring them together comfortably and honestly with this theme. It was important for me to present Indigenous art to audiences, and I felt it was most accurate to be seen as part of Australian art history, rather than a separate exhibition of its own.’ </p><p>([Triển lãm] là sự kết hợp tuyệt vời giữa hai loại hình nghệ thuật khác nhau, cho phép tôi kết hợp chúng một cách thoải mái và chân thành với chủ đề này. Điều quan trọng đối với tôi là giới thiệu nghệ thuật bản địa đến công chúng, và tôi cảm thấy chính xác nhất là nên xem nó như một phần của lịch sử nghệ thuật Úc, chứ không phải là một triển lãm riêng biệt.)</p>", "36": "<p>36 A</p><p>Câu hỏi: <i>By referring to China, Mendelssohn is making the point that</i>A.    having an exhibition in London is not as important as it used to be.B.    young artists in Britain are not interested in Australian art.C.    art from Shanghai is more important than Australian art.D.    New York is still a preferred destination for young artists.</p><p>(<i>Khi nhắc đến Trung Quốc, Mendelssohn muốn nói rằng</i>A.    tổ chức triển lãm ở London không còn quan trọng như trước nữa.B.    nghệ sĩ trẻ ở Anh không quan tâm nghệ thuật Úc.C.    nghệ thuật Thượng Hải quan trọng hơn nghệ thuật Úc.D.    New York vẫn là nơi nghệ sĩ trẻ muốn đến nhất.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Meanwhile, Australian critic Mendelssohn also points out that London is increasingly less important to today’s generation of artists, and this somewhat weakens the ceremony surrounding the exhibition in London.  </p><p>When I was growing up, London was the destination, and then when I was at university all the smart young things wanted to go to New York,’ she added. ‘Now they want to go everywhere.  </p><p>(Trong khi đó, nhà phê bình người Úc Mendelssohn cũng chỉ ra rằng London ngày càng ít quan trọng đối với thế hệ nghệ sĩ ngày nay, và điều này phần nào làm suy yếu tính trang trọng xung quanh triển lãm ở London.</p><p>&quot;Khi tôi còn nhỏ, London là điểm đến, rồi khi tôi học đại học, tất cả những người trẻ thông minh đều muốn đến New York&quot;, cô ấy nói thêm. &quot;Bây giờ họ muốn đi khắp mọi nơi.&quot;)</p>", "37": "<p>37 F shows an acceptance of the unique qualities of Australian art.</p><p>Câu hỏi: <i>In spite of its conservatism, the Royal Academy exhibition _______</i></p><p>(Mặc dù còn khá bảo thủ, triển lãm của Học viện Hoàng gia ______)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: And while Mendelssohn’s concern over the exhibition’s conventional selection is valid, the Academy is nevertheless embracing the peculiarities of Australian art from the mid-19th century onward, albeit within the boundaries of landscape.</p><p>(Và mặc dù mối lo của Mendelssohn về cách chọn tác phẩm khá truyền thống là có cơ sở, Học viện vẫn đang đón nhận những nét độc đáo riêng của nghệ thuật Úc từ giữa thế kỷ 19 trở đi, dù vẫn trong phạm vi chủ đề phong cảnh.)</p><p>=&gt; Đáp án: F shows an acceptance of the unique qualities of Australian art. (F cho thấy sự công nhận những nét độc đáo riêng của nghệ thuật Úc )</p>", "38": "<p>38 E demonstrates a strong European flavour.</p><p>Câu hỏi: <i>Australian art of the early to mid-1800s _______</i></p><p>(Nghệ thuật Úc đầu đến giữa thế kỷ 19 ______)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: ‘Certainly the influence of English, French or German art is much more evident in the early periods, in the early 1800s to mid-1800s,’</p><p>(Chắc chắn ảnh hưởng của nghệ thuật Anh, Pháp hoặc Đức thể hiện rõ hơn nhiều trong giai đoạn đầu, từ đầu đến giữa thế kỷ 19.)</p><p>=&gt; Đáp án: E demonstrates a strong European flavour. (E mang đậm phong cách châu Âu )</p>", "39": "<p>39 A reflects the mood created by the natural environment.</p><p>Câu hỏi: <i>The modern work by Gladwell chosen for the exhibition ________</i></p><p>(Tác phẩm hiện đại của Gladwell được chọn cho triển lãm ______)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: Gladwell’s most famous piece, which is featured in the exhibition, is Storm Sequence (2000), a video of Gladwell skateboarding on the Bondi seafront as one of Sydney’s signature brutal storms lingers offshore. It is his acknowledgment of landscape (or seascape) tradition, coloured by Gladwell’s own individualism. ‘To exhibit my work in this show might make some sense because I was interested in Turner and the idea of atmosphere affecting vision</p><p>(Tác phẩm nổi tiếng nhất của Gladwell, được trưng bày trong triển lãm, là Chuỗi Bão (2000), một video ghi lại cảnh Gladwell trượt ván trên bờ biển Bondi khi một trong những cơn bão dữ dội đặc trưng của Sydney vẫn còn hoành hành ngoài khơi. Đó là sự thừa nhận của ông về truyền thống phong cảnh (hoặc cảnh biển), được tô điểm bởi cá tính riêng của Gladwell. “Việc trưng bày tác phẩm của tôi trong triển lãm này có lẽ có ý nghĩa vì tôi quan tâm đến Turner và ý tưởng về bầu không khí ảnh hưởng đến thị giác.”)</p><p>=&gt; Đáp án: A reflects the mood created by the natural environment. (A  phản ánh bầu không khí do thiên nhiên tạo ra )</p>", "40": "<p>40 C demonstrates an understanding of the historical importance of the land.</p><p>Câu hỏi: <i>Including Aboriginal art in the exhibition _______</i></p><p>(Việc đưa nghệ thuật thổ dân Aboriginal vào triển lãm _______)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: These works warrant a prominent position because they were ‘first’. Over the last couple of decades, London has hosted many successful exhibitions of Aboriginal art in smaller spaces, but for Soriano, Australia represents an opportunity to place such art within the context of new relationships to the art of the settlers and white Australia. ‘One of the reasons landscape was seen as being the right theme was because Australian art started in and on the landscape,’</p><p>(Những tác phẩm này xứng đáng được đặt ở vị trí nổi bật vì chúng là những tác phẩm “đầu tiên”. Trong vài thập kỷ qua, London đã tổ chức nhiều triển lãm thành công về nghệ thuật thổ dân trong những không gian nhỏ hơn, nhưng đối với Soriano, Úc đại diện cho một cơ hội để đặt loại hình nghệ thuật này trong bối cảnh các mối quan hệ mới với nghệ thuật của những người định cư và người Úc da trắng. “Một trong những lý do khiến phong cảnh được coi là chủ đề phù hợp là vì nghệ thuật Úc bắt đầu từ và trên phong cảnh”,)</p><p>=&gt; Đáp án: C demonstrates an understanding of the historical importance of the land. (C thể hiện sự hiểu biết về tầm quan trọng lịch sử của vùng đất )</p>"}, "transcriptSegments": {"1": [{"id": "r1-p1", "text": "Australians living or traveling in rural and remote areas can face particular difficulties when they need medical care. Hundreds of kilometres from major cities and many hours by road from the closest hospital or clinic, some rural Australians do not have easy access to doctors, nurses and dentists.", "html": "<p>Australians living or traveling in rural and remote areas can face particular difficulties when they need medical care. Hundreds of kilometres from major cities and many hours by road from the closest hospital or clinic, some rural Australians do not have easy access to doctors, nurses and dentists.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p2", "text": "Organisations such as the Royal Flying Doctor Service (RFDS) have been established to bring health services to outback Australian communities. The RFDS provides free medical care to people who live, work or travel in remote and regional parts of Australia. This non-profit organisation is the oldest and largest airborne health service of its kind in the world, and since 1928 it has used small planes to reach Australia's most far-away communities.", "html": "<p>Organisations such as the Royal Flying Doctor Service (RFDS) have been established to bring health services to outback Australian communities. The RFDS provides free medical care to people who live, work or travel in remote and regional parts of Australia. This non-profit organisation is the oldest and largest airborne health service of its kind in the world, and since 1928 it has used small planes to reach Australia&#x27;s most far-away communities.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p3", "text": "In recent years, the RFDS has also started to fly dentists to regional Australia. As well as offering mobile dental clinics, the RFDS offers a range of preventative and educational services. Looking after the teeth of people in remote areas presents special challenges. These include providing care to disparate communities with no established dental facilities, and dealing with higher incidences of other diseases which are linked to, or caused by poor dental health.", "html": "<p>In recent years, the RFDS has also started to fly dentists to regional Australia. As well as offering mobile dental clinics, the RFDS offers a range of preventative and educational services. Looking after the teeth of people in remote areas presents special challenges. These include providing care to disparate communities with no established dental facilities, and dealing with higher incidences of other diseases which are linked to, or caused by poor dental health.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p4", "text": "People in remote areas have very infrequent visits by health staff. RFDS dentists might only visit a community once every few months, or sometimes once per year. Because of infrequent dentist visits, patients in these areas often need to put up with their dental problems before they can get treatment; consequently, people in remote areas are more likely to have tooth decay (the blackening and deterioration of teeth) and develop gum and other mouth diseases.", "html": "<p>People in remote areas have very infrequent visits by health staff. RFDS dentists might only visit a community once every few months, or sometimes once per year. Because of infrequent dentist visits, patients in these areas often need to put up with their dental problems before they can get treatment; consequently, people in remote areas are more likely to have tooth decay (the blackening and deterioration of teeth) and develop gum and other mouth diseases.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p5", "text": "In some locations that the RFDS visits, there are no suitable dental facilities, so dentists have to bring everything with them. This includes drills, dentists' chairs, portable X-ray machines, and computers for keeping track of patients' treatments. Equipment can weigh up to 100 kilograms, and since the small planes that transport dentists have limited space, dentists cannot always bring everything that they need.", "html": "<p>In some locations that the RFDS visits, there are no suitable dental facilities, so dentists have to bring everything with them. This includes drills, dentists&#x27; chairs, portable X-ray machines, and computers for keeping track of patients&#x27; treatments. Equipment can weigh up to 100 kilograms, and since the small planes that transport dentists have limited space, dentists cannot always bring everything that they need.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p6", "text": "While dentists in town or city centres can specialise in certain types of treatment, RFDS dentists need to be 'all-rounders'. They need to be able to do all kinds of dental procedures, as they don't have the ability to refer patients to more specialised dentists. Even with their broad experience, there are some services that are particularly challenging for RFDS dentists. For example, dentures (artificial teeth) can be very difficult to provide, as they need to be the right shape and size for the patient, and this requires many visits over a long period of time. As a result, it is not practical to make dentures available.", "html": "<p>While dentists in town or city centres can specialise in certain types of treatment, RFDS dentists need to be &#x27;all-rounders&#x27;. They need to be able to do all kinds of dental procedures, as they don&#x27;t have the ability to refer patients to more specialised dentists. Even with their broad experience, there are some services that are particularly challenging for RFDS dentists. For example, dentures (artificial teeth) can be very difficult to provide, as they need to be the right shape and size for the patient, and this requires many visits over a long period of time. As a result, it is not practical to make dentures available.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p7", "text": "Some chronic illnesses are more common in remote communities than in the rest of Australia. These illnesses can in turn lead to a lowered resistance to infection, including gum and other oral infections. As a result, people in outback Australian communities are more likely to experience oral health problems than city folk, and this poses extra challenges for both the dentists and the doctors of the RFDS.", "html": "<p>Some chronic illnesses are more common in remote communities than in the rest of Australia. These illnesses can in turn lead to a lowered resistance to infection, including gum and other oral infections. As a result, people in outback Australian communities are more likely to experience oral health problems than city folk, and this poses extra challenges for both the dentists and the doctors of the RFDS.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p8", "text": "Because there aren't a lot of dental services in remote areas, people living in these areas also receive less education about good dental hygiene than their city counterparts do. Australians in very remote communities might not be aware of things that people in cities take for granted, such as the importance of daily tooth brushing. Also, basic dental hygiene items such as toothpaste and toothbrushes can be more expensive in outback areas. Many people are on low incomes, meaning they have extra difficulty affording these products. If this is the case, the RFDS supplies these.", "html": "<p>Because there aren&#x27;t a lot of dental services in remote areas, people living in these areas also receive less education about good dental hygiene than their city counterparts do. Australians in very remote communities might not be aware of things that people in cities take for granted, such as the importance of daily tooth brushing. Also, basic dental hygiene items such as toothpaste and toothbrushes can be more expensive in outback areas. Many people are on low incomes, meaning they have extra difficulty affording these products. If this is the case, the RFDS supplies these.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p9", "text": "As well as treating patients, RFDS dentists try to focus on preventative oral health and educate their patients on good oral hygiene, such as tooth brushing and flossing. The RFDS also provides mouthguards for young sports players. Playing contact sports, such as rugby league or Australian rules football, can damage young people's teeth, so mouthguards provide protection which prevents accidental injuries.", "html": "<p>As well as treating patients, RFDS dentists try to focus on preventative oral health and educate their patients on good oral hygiene, such as tooth brushing and flossing. The RFDS also provides mouthguards for young sports players. Playing contact sports, such as rugby league or Australian rules football, can damage young people&#x27;s teeth, so mouthguards provide protection which prevents accidental injuries.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p10", "text": "Adding fluoride to water supplies has been proven to reduce the incidence of tooth decay in many parts of the world. City dwellers in Australia use water supplies that have been fluoridated, and their rates of tooth decay are lower because of this. In remote areas, it is not practical to fluoridate drinking water supplies, and so people living in these areas are more subject to tooth decay. As a result, it is particularly important that people living in areas without fluoridated water pay special attention to regular brushing of their teeth with fluoridated toothpaste.", "html": "<p>Adding fluoride to water supplies has been proven to reduce the incidence of tooth decay in many parts of the world. City dwellers in Australia use water supplies that have been fluoridated, and their rates of tooth decay are lower because of this. In remote areas, it is not practical to fluoridate drinking water supplies, and so people living in these areas are more subject to tooth decay. As a result, it is particularly important that people living in areas without fluoridated water pay special attention to regular brushing of their teeth with fluoridated toothpaste.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p11", "text": "Despite many challenges, the RFDS continues to offer much-needed dental and medical support. Its presence in isolated communities greatly improves the quality of dental health, and supports important oral hygiene and health initiatives.", "html": "<p>Despite many challenges, the RFDS continues to offer much-needed dental and medical support. Its presence in isolated communities greatly improves the quality of dental health, and supports important oral hygiene and health initiatives.</p>", "letter": null, "headingQuestion": null}], "2": [{"id": "r2-p1", "text": "Researchers agree that art participation is an important leisure pursuit, with benefits not only to the individual, but also to the community. Art participation can be active, where people create or perform the art, or passive, as is the case when an audience views a performance or a person visits a gallery.", "html": "<p><i>Researchers agree that art participation is an important leisure pursuit, with benefits not only to the individual, but also to the community. Art participation can be active, where people create or perform the art, or passive, as is the case when an audience views a performance or a person visits a gallery.</i></p>", "letter": null, "headingQuestion": null}, {"id": "r2-p2", "text": "Researcher Howard Spector suggests that active art experiences benefit all age groups by providing individuals with the means to freely and creatively express themselves. Self-expression, in turn, promotes individuality, bolsters self-confidence and improves motivation and attitudes towards academic performance. Both active and passive art experiences can provide the benefits of discovery, stimulation and relaxation (Oliphant 2000). Furthermore, people's participation in art enhances their development and expands their thoughts about culture. In short, art can make individuals more socially conscious.", "html": "<p>Researcher Howard Spector suggests that active art experiences benefit all age groups by providing individuals with the means to freely and creatively express themselves. Self-expression, in turn, promotes individuality, bolsters self-confidence and improves motivation and attitudes towards academic performance. Both active and passive art experiences can provide the benefits of discovery, stimulation and relaxation (Oliphant 2000). Furthermore, people&#x27;s participation in art enhances their development and expands their thoughts about culture. In short, art can make individuals more socially conscious.</p>", "letter": null, "headingQuestion": 14}, {"id": "r2-p3", "text": "Communities committed to providing opportunities for experiencing art are considered more livable because they are attractive to businesses and industry and they offer a higher quality of life for residents (Riley 2002). Tourism is strongly linked to art; art is believed to stimulate tourism in a community, and vice versa. Art-related tourism generates tourists and revenue, attracts high-income consumers, extends the tourist season and is a \"green\" form of the industry (Hughes 2000). Revitalization efforts have increased in many cities because of the strong presence of art opportunities.", "html": "<p>Communities committed to providing opportunities for experiencing art are considered more livable because they are attractive to businesses and industry and they offer a higher quality of life for residents (Riley 2002). Tourism is strongly linked to art; art is believed to stimulate tourism in a community, and vice versa. Art-related tourism generates tourists and revenue, attracts high-income consumers, extends the tourist season and is a &quot;green&quot; form of the industry (Hughes 2000). Revitalization efforts have increased in many cities because of the strong presence of art opportunities.</p>", "letter": null, "headingQuestion": 15}, {"id": "r2-p4", "text": "Art programs can be highly effective in reducing community problems related to delinquent behavior and truancy in youth (Spector 2000). The Philadelphia Department of Recreation Mural Arts Program (MAP) is one such program. It began in the early 1980s when the city undertook to remove graffiti in the city while creating a positive, productive and creative outlet for adjudicated graffiti artists, as they used their talents to beautify public spaces through the creation of murals, instilling a sense of pride, excellence, diligence and civic responsibility.", "html": "<p>Art programs can be highly effective in reducing community problems related to delinquent behavior and truancy in youth (Spector 2000). The Philadelphia Department of Recreation Mural Arts Program (MAP) is one such program. It began in the early 1980s when the city undertook to remove graffiti in the city while creating a positive, productive and creative outlet for adjudicated graffiti artists, as they used their talents to beautify public spaces through the creation of murals, instilling a sense of pride, excellence, diligence and civic responsibility.</p>", "letter": null, "headingQuestion": null}, {"id": "r2-p5", "text": "In recognition of these and other benefits, communities are finding many ways to ensure that the public is provided with opportunities to experience art. Public art programs are one way. These programs are typically administered by government, which commissions or mandates works of art for display in public spaces. Public art works can include street furniture, decorations, paving and landmarks, and may take on many forms, including sculpture, decorative ironwork, mosaic flooring and murals. The primary purpose of public art is to bring art into everyday life, to energize public spaces and to arouse society's thinking and imagination.", "html": "<p>In recognition of these and other benefits, communities are finding many ways to ensure that the public is provided with opportunities to experience art. Public art programs are one way. These programs are typically administered by government, which commissions or mandates works of art for display in public spaces. Public art works can include street furniture, decorations, paving and landmarks, and may take on many forms, including sculpture, decorative ironwork, mosaic flooring and murals. The primary purpose of public art is to bring art into everyday life, to energize public spaces and to arouse society&#x27;s thinking and imagination.</p>", "letter": null, "headingQuestion": 16}, {"id": "r2-p6", "text": "Despite the significant benefits that art participation can offer to individuals and communities, only 35 percent of the American adult population visit museums or galleries at least once during the year, and only about 25 percent attend a live performance (Bradshaw 1998). Even fewer (14 percent) participate directly in photography, painting, drawing, sculpting, dance (other than ballet), creative writing or classical music. If art experiences are so beneficial, why aren't more people participating?", "html": "<p>Despite the significant benefits that art participation can offer to individuals and communities, only 35 percent of the American adult population visit museums or galleries at least once during the year, and only about 25 percent attend a live performance (Bradshaw 1998). Even fewer (14 percent) participate directly in photography, painting, drawing, sculpting, dance (other than ballet), creative writing or classical music. If art experiences are so beneficial, why aren&#x27;t more people participating?</p>", "letter": null, "headingQuestion": 17}, {"id": "r2-p7", "text": "To help researchers shed light on this question, the RAND Corporation, a nonprofit institution that helps improve policy and decision-making through objective research and analysis, developed \"A Behavior Model of the Participant Decision\", which can be used to investigate people's inclinations about participating in an art activity (Yoshitomi 2000). According to Yoshitomi, each person has a disposition related to his or her interest in engaging in an art activity; a person's disposition is based on sociodemographic characteristics, social or cultural identity, personality and previous experience. The RAND model clusters participants into three groups according to their disposition toward art participation: those disinclined to participate; those inclined to participate; and those currently participating.", "html": "<p>To help researchers shed light on this question, the RAND Corporation, a nonprofit institution that helps improve policy and decision-making through objective research and analysis, developed &quot;A Behavior Model of the Participant Decision&quot;, which can be used to investigate people&#x27;s inclinations about participating in an art activity (Yoshitomi 2000). According to Yoshitomi, each person has a disposition related to his or her interest in engaging in an art activity; a person&#x27;s disposition is based on sociodemographic characteristics, social or cultural identity, personality and previous experience. The RAND model clusters participants into three groups according to their disposition toward art participation: those disinclined to participate; those inclined to participate; and those currently participating.</p>", "letter": null, "headingQuestion": null}, {"id": "r2-p8", "text": "The RAND findings reveal that the disinclined perceive themselves as being uncomfortable or unfamiliar with art. This disposition might occur among people who do not value art and who have not received art education, or who perceive themselves as unsophisticated or lacking skill to participate. The inclined are interested in participating, but may be constrained by particular barriers such as cost, time, and proper attire. Current participants are those who are involved, and influence or encourage others to participate. Researchers suggest that a strong relationship exists between childhood and adult art participation rates. Individuals with a greater number of childhood art experiences are more likely to have higher rates of participation as adults. Although 90 percent of Americans believe art instruction is important for children and should be offered in schools, almost 40 percent of schools either offer no art instruction or have art instructors with no formal art training.", "html": "<p>The RAND findings reveal that the disinclined perceive themselves as being uncomfortable or unfamiliar with art. This disposition might occur among people who do not value art and who have not received art education, or who perceive themselves as unsophisticated or lacking skill to participate. The inclined are interested in participating, but may be constrained by particular barriers such as cost, time, and proper attire. Current participants are those who are involved, and influence or encourage others to participate. Researchers suggest that a strong relationship exists between childhood and adult art participation rates. Individuals with a greater number of childhood art experiences are more likely to have higher rates of participation as adults. Although 90 percent of Americans believe art instruction is important for children and should be offered in schools, almost 40 percent of schools either offer no art instruction or have art instructors with no formal art training.</p>", "letter": null, "headingQuestion": 18}, {"id": "r2-p9", "text": "One recreation organization working to make sure children get exposed to art is the Boys and Girls Clubs of America, which offer two innovative programs: The National Photography Program and the National Fine Arts Exhibit. Both are designed to get children excited about art. The photography program promotes new art that is technologically produced, including video and computer graphics, but primarily focuses on photography. The program provides club members with the opportunity to achieve personal growth and receive artistic recognition through instruction in photography. Participants also display their work at local, regional and national photography contests. The second program is the Fine Arts Exhibit. This encourages artistic expression, creativity, cultural appreciation and the development of artistic skills through classes, special events, exhibits and competitions. It allows participants to explore a variety of mediums, including drawing, painting, print making, collage and sculpture.", "html": "<p>One recreation organization working to make sure children get exposed to art is the Boys and Girls Clubs of America, which offer two innovative programs: The National Photography Program and the National Fine Arts Exhibit. Both are designed to get children excited about art. The photography program promotes new art that is technologically produced, including video and computer graphics, but primarily focuses on photography. The program provides club members with the opportunity to achieve personal growth and receive artistic recognition through instruction in photography. Participants also display their work at local, regional and national photography contests. The second program is the Fine Arts Exhibit. This encourages artistic expression, creativity, cultural appreciation and the development of artistic skills through classes, special events, exhibits and competitions. It allows participants to explore a variety of mediums, including drawing, painting, print making, collage and sculpture.</p>", "letter": null, "headingQuestion": 19}, {"id": "r2-p10", "text": "Because art experiences provide so many important benefits to individuals and communities, it is important for community programs to facilitate opportunities and provide encouragement to increase participation in a variety of programs.", "html": "<p>Because art experiences provide so many important benefits to individuals and communities, it is important for community programs to facilitate opportunities and provide encouragement to increase participation in a variety of programs.</p>", "letter": null, "headingQuestion": null}], "3": [{"id": "r3-p1", "text": "A For the casual viewer, the exhibition of landscapes, Australia, selected by the Royal Academy of Art will be a spectacular guide through Australian art history. Included in the exhibition are a range of artists and styles, dating from the earliest days of colonial art and progressing through expressionism and modernism to the artists of the 20th century, culminating with the current generation of Australian artists. It is hardly surprising, then, that this results in a flexible, wide-ranging notion of landscape.", "html": "<p><b>A</b> For the casual viewer, the exhibition of landscapes, Australia, selected by the Royal Academy of Art will be a spectacular guide through Australian art history. Included in the exhibition are a range of artists and styles, dating from the earliest days of colonial art and progressing through expressionism and modernism to the artists of the 20th century, culminating with the current generation of Australian artists. It is hardly surprising, then, that this results in a flexible, wide-ranging notion of landscape.</p>", "letter": "A", "headingQuestion": null}, {"id": "r3-p2", "text": "B But this landmark exhibition gives rise to some questions, and perhaps problems, regarding Britain’s relationship with its former colony. By choosing a style of painting at which British artists excel, the Academy could be seen as inviting criticism that hints at a telling attitude towards art by comparison. But it is the very theme of landscape painting that makes this a controversial selection. To consider if condescending is perhaps too strong, but for Joanna Mendelssohn, Australian critic and Associate Professor at the University of NSW’s College of Fine Arts (COFA), there is a suggestion that British artistic values have directed this exhibition, rather than allowing Australia the freedom to demonstrate its maturity.", "html": "<p><b>B</b> But this landmark exhibition gives rise to some questions, and perhaps problems, regarding Britain’s relationship with its former colony. By choosing a style of painting at which British artists excel, the Academy could be seen as inviting criticism that hints at a telling attitude towards art by comparison. But it is the very theme of landscape painting that makes this a controversial selection. To consider if condescending is perhaps too strong, but for Joanna Mendelssohn, Australian critic and Associate Professor at the University of NSW’s College of Fine Arts (COFA), there is a suggestion that British artistic values have directed this exhibition, rather than allowing Australia the freedom to demonstrate its maturity.</p>", "letter": "B", "headingQuestion": null}, {"id": "r3-p3", "text": "C What Mendelssohn found surprising about the exhibition was the underlying rules for the selection of works seemed to have been so conservative. Since the landscape is a very strong British artistic theme, it appeared to her that when the British looked to the art of a former colony, there was a tendency for them to think that those colonies would continue to be like the British themselves. In reviewing Australian art, the British insisted on looking at the genre of landscape painting.", "html": "<p><b>C</b> What Mendelssohn found surprising about the exhibition was the underlying rules for the selection of works seemed to have been so conservative. Since the landscape is a very strong British artistic theme, it appeared to her that when the British looked to the art of a former colony, there was a tendency for them to think that those colonies would continue to be like the British themselves. In reviewing Australian art, the British insisted on looking at the genre of landscape painting.</p>", "letter": "C", "headingQuestion": null}, {"id": "r3-p4", "text": "D Because of colonial ties, it was inevitable during Australian art’s formative years that it would reflect Britain’s devotion to the beloved landscape before its own character and idiosyncrasies took shape. And while Mendelssohn’s concern over the exhibition’s conventional selection is valid, the Academy is nevertheless embracing the peculiarities of Australian art from the mid-19th century onward, albeit within the boundaries of landscape.", "html": "<p><b>D</b> Because of colonial ties, it was inevitable during Australian art’s formative years that it would reflect Britain’s devotion to the beloved landscape before its own character and idiosyncrasies took shape. And while Mendelssohn’s concern over the exhibition’s conventional selection is valid, the Academy is nevertheless embracing the peculiarities of Australian art from the mid-19th century onward, albeit within the boundaries of landscape.</p>", "letter": "D", "headingQuestion": null}, {"id": "r3-p5", "text": "E Australia is curated by Kathleen Soriano, director of exhibitions at the Royal Academy. ‘Certainly the influence of English, French or German art is much more evident in the early periods, in the early 1800s to mid-1800s,’ she says. ‘What I wanted to show was how Australian art develops a real distinctiveness, associated with the landscape and the light.’", "html": "<p><b>E </b>Australia is curated by Kathleen Soriano, director of exhibitions at the Royal Academy. ‘Certainly the influence of English, French or German art is much more evident in the early periods, in the early 1800s to mid-1800s,’ she says. ‘What I wanted to show was how Australian art develops a real distinctiveness, associated with the landscape and the light.’</p>", "letter": "E", "headingQuestion": null}, {"id": "r3-p6", "text": "F The fusion of ‘tradition’ of the European kind with something more specifically Australian, and often personal, is crucial to the exhibition and extends particularly to some of the more contemporary artists involved. Sydney-born video artist Shaun Gladwell is a good example of this. Gladwell’s most famous piece, which is featured in the exhibition, is Storm Sequence (2000), a video of Gladwell skateboarding on the Bondi seafront as one of Sydney’s signature brutal storms lingers offshore. It is his acknowledgment of landscape (or seascape) tradition, coloured by Gladwell’s own individualism. ‘To exhibit my work in this show might make some sense because I was interested in Turner and the idea of atmosphere affecting vision, something I was really interested in around the time of Storm Sequence. I was thinking about this tradition of Romantic landscape, but I wanted to make it personal,’ says Gladwell. But he didn’t want to just embark on borrowing imagery from elsewhere. He wanted to bring it to his experience and his world through skateboarding and beach culture.", "html": "<p><b>F </b>The fusion of ‘tradition’ of the European kind with something more specifically Australian, and often personal, is crucial to the exhibition and extends particularly to some of the more contemporary artists involved. Sydney-born video artist Shaun Gladwell is a good example of this. Gladwell’s most famous piece, which is featured in the exhibition, is Storm Sequence (2000), a video of Gladwell skateboarding on the Bondi seafront as one of Sydney’s signature brutal storms lingers offshore. It is his acknowledgment of landscape (or seascape) tradition, coloured by Gladwell’s own individualism. ‘To exhibit my work in this show might make some sense because I was interested in Turner and the idea of atmosphere affecting vision, something I was really interested in around the time of Storm Sequence. I was thinking about this tradition of Romantic landscape, but I wanted to make it personal,’ says Gladwell. But he didn’t want to just embark on borrowing imagery from elsewhere. He wanted to bring it to his experience and his world through skateboarding and beach culture.</p>", "letter": "F", "headingQuestion": null}, {"id": "r3-p7", "text": "G So while it may seem narrow for Britain to reduce Australian art to the genre of landscape, there can be little denying that British landscape painting is still relevant to a current generation of Australian practitioners, however indirectly.", "html": "<p><b>G</b> So while it may seem narrow for Britain to reduce Australian art to the genre of landscape, there can be little denying that British landscape painting is still relevant to a current generation of Australian practitioners, however indirectly.</p>", "letter": "G", "headingQuestion": null}, {"id": "r3-p8", "text": "H Visitors to the exhibition encounter Australian Aboriginal art first, the idea being that these works warrant a prominent position because they were ‘first’. Over the last couple of decades, London has hosted many successful exhibitions of Aboriginal art in smaller spaces, but for Soriano, Australia represents an opportunity to place such art within the context of new relationships to the art of the settlers and white Australia. ‘One of the reasons landscape was seen as being the right theme was because Australian art started in and on the landscape,’ she says. ‘[The exhibition] is a beautiful meshing of the two different kinds of art that allowed me to bring them together comfortably and honestly with this theme. It was important for me to present Indigenous art to audiences, and I felt it was most accurate to be seen as part of Australian art history, rather than a separate exhibition of its own.’", "html": "<p><b>H</b> Visitors to the exhibition encounter Australian Aboriginal art first, the idea being that these works warrant a prominent position because they were ‘first’. Over the last couple of decades, London has hosted many successful exhibitions of Aboriginal art in smaller spaces, but for Soriano, Australia represents an opportunity to place such art within the context of new relationships to the art of the settlers and white Australia. ‘One of the reasons landscape was seen as being the right theme was because Australian art started in and on the landscape,’ she says. ‘[The exhibition] is a beautiful meshing of the two different kinds of art that allowed me to bring them together comfortably and honestly with this theme. It was important for me to present Indigenous art to audiences, and I felt it was most accurate to be seen as part of Australian art history, rather than a separate exhibition of its own.’</p>", "letter": "H", "headingQuestion": null}, {"id": "r3-p9", "text": "I Meanwhile, Australian critic Mendelssohn also points out that London is increasingly less important to today’s generation of artists, and this somewhat weakens the ceremony surrounding the exhibition in London. ‘China is the most important art market in the world,’ she says. ‘If you’ve made it in Shanghai, you’ve made it. The world has changed. My students in Australia, who come from all over the world, really want to see Venice Biennale and Art Basel, but they’re less interested in going to London. When I was growing up, London was the destination, and then when I was at university all the smart young things wanted to go to New York,’ she added. ‘Now they want to go everywhere. There’s no such thing as the centre and the periphery like there used to be. It’s much more complicated.’", "html": "<p><b>I</b> Meanwhile, Australian critic Mendelssohn also points out that London is increasingly less important to today’s generation of artists, and this somewhat weakens the ceremony surrounding the exhibition in London. ‘China is the most important art market in the world,’ she says. ‘If you’ve made it in Shanghai, you’ve made it. The world has changed. My students in Australia, who come from all over the world, really want to see Venice Biennale and Art Basel, but they’re less interested in going to London. When I was growing up, London was the destination, and then when I was at university all the smart young things wanted to go to New York,’ she added. ‘Now they want to go everywhere. There’s no such thing as the centre and the periphery like there used to be. It’s much more complicated.’</p>", "letter": "I", "headingQuestion": null}]}, "transcripts": {"1": "<p>Australians living or traveling in rural and remote areas can face particular difficulties when they need medical care. Hundreds of kilometres from major cities and many hours by road from the closest hospital or clinic, some rural Australians do not have easy access to doctors, nurses and dentists.</p><p>Organisations such as the Royal Flying Doctor Service (RFDS) have been established to bring health services to outback Australian communities. The RFDS provides free medical care to people who live, work or travel in remote and regional parts of Australia. This non-profit organisation is the oldest and largest airborne health service of its kind in the world, and since 1928 it has used small planes to reach Australia&#x27;s most far-away communities.</p><p>In recent years, the RFDS has also started to fly dentists to regional Australia. As well as offering mobile dental clinics, the RFDS offers a range of preventative and educational services. Looking after the teeth of people in remote areas presents special challenges. These include providing care to disparate communities with no established dental facilities, and dealing with higher incidences of other diseases which are linked to, or caused by poor dental health.</p><p>People in remote areas have very infrequent visits by health staff. RFDS dentists might only visit a community once every few months, or sometimes once per year. Because of infrequent dentist visits, patients in these areas often need to put up with their dental problems before they can get treatment; consequently, people in remote areas are more likely to have tooth decay (the blackening and deterioration of teeth) and develop gum and other mouth diseases.</p><p>In some locations that the RFDS visits, there are no suitable dental facilities, so dentists have to bring everything with them. This includes drills, dentists&#x27; chairs, portable X-ray machines, and computers for keeping track of patients&#x27; treatments. Equipment can weigh up to 100 kilograms, and since the small planes that transport dentists have limited space, dentists cannot always bring everything that they need.</p><p>While dentists in town or city centres can specialise in certain types of treatment, RFDS dentists need to be &#x27;all-rounders&#x27;. They need to be able to do all kinds of dental procedures, as they don&#x27;t have the ability to refer patients to more specialised dentists. Even with their broad experience, there are some services that are particularly challenging for RFDS dentists. For example, dentures (artificial teeth) can be very difficult to provide, as they need to be the right shape and size for the patient, and this requires many visits over a long period of time. As a result, it is not practical to make dentures available.</p><p>Some chronic illnesses are more common in remote communities than in the rest of Australia. These illnesses can in turn lead to a lowered resistance to infection, including gum and other oral infections. As a result, people in outback Australian communities are more likely to experience oral health problems than city folk, and this poses extra challenges for both the dentists and the doctors of the RFDS.</p><p>Because there aren&#x27;t a lot of dental services in remote areas, people living in these areas also receive less education about good dental hygiene than their city counterparts do. Australians in very remote communities might not be aware of things that people in cities take for granted, such as the importance of daily tooth brushing. Also, basic dental hygiene items such as toothpaste and toothbrushes can be more expensive in outback areas. Many people are on low incomes, meaning they have extra difficulty affording these products. If this is the case, the RFDS supplies these.</p><p>As well as treating patients, RFDS dentists try to focus on preventative oral health and educate their patients on good oral hygiene, such as tooth brushing and flossing. The RFDS also provides mouthguards for young sports players. Playing contact sports, such as rugby league or Australian rules football, can damage young people&#x27;s teeth, so mouthguards provide protection which prevents accidental injuries.</p><p>Adding fluoride to water supplies has been proven to reduce the incidence of tooth decay in many parts of the world. City dwellers in Australia use water supplies that have been fluoridated, and their rates of tooth decay are lower because of this. In remote areas, it is not practical to fluoridate drinking water supplies, and so people living in these areas are more subject to tooth decay. As a result, it is particularly important that people living in areas without fluoridated water pay special attention to regular brushing of their teeth with fluoridated toothpaste.</p><p>Despite many challenges, the RFDS continues to offer much-needed dental and medical support. Its presence in isolated communities greatly improves the quality of dental health, and supports important oral hygiene and health initiatives.</p>", "2": "<p><i>Researchers agree that art participation is an important leisure pursuit, with benefits not only to the individual, but also to the community. Art participation can be active, where people create or perform the art, or passive, as is the case when an audience views a performance or a person visits a gallery.</i></p><p>Researcher Howard Spector suggests that active art experiences benefit all age groups by providing individuals with the means to freely and creatively express themselves. Self-expression, in turn, promotes individuality, bolsters self-confidence and improves motivation and attitudes towards academic performance. Both active and passive art experiences can provide the benefits of discovery, stimulation and relaxation (Oliphant 2000). Furthermore, people&#x27;s participation in art enhances their development and expands their thoughts about culture. In short, art can make individuals more socially conscious.</p><p>Communities committed to providing opportunities for experiencing art are considered more livable because they are attractive to businesses and industry and they offer a higher quality of life for residents (Riley 2002). Tourism is strongly linked to art; art is believed to stimulate tourism in a community, and vice versa. Art-related tourism generates tourists and revenue, attracts high-income consumers, extends the tourist season and is a &quot;green&quot; form of the industry (Hughes 2000). Revitalization efforts have increased in many cities because of the strong presence of art opportunities.</p><p>Art programs can be highly effective in reducing community problems related to delinquent behavior and truancy in youth (Spector 2000). The Philadelphia Department of Recreation Mural Arts Program (MAP) is one such program. It began in the early 1980s when the city undertook to remove graffiti in the city while creating a positive, productive and creative outlet for adjudicated graffiti artists, as they used their talents to beautify public spaces through the creation of murals, instilling a sense of pride, excellence, diligence and civic responsibility.</p><p>In recognition of these and other benefits, communities are finding many ways to ensure that the public is provided with opportunities to experience art. Public art programs are one way. These programs are typically administered by government, which commissions or mandates works of art for display in public spaces. Public art works can include street furniture, decorations, paving and landmarks, and may take on many forms, including sculpture, decorative ironwork, mosaic flooring and murals. The primary purpose of public art is to bring art into everyday life, to energize public spaces and to arouse society&#x27;s thinking and imagination.</p><p>Despite the significant benefits that art participation can offer to individuals and communities, only 35 percent of the American adult population visit museums or galleries at least once during the year, and only about 25 percent attend a live performance (Bradshaw 1998). Even fewer (14 percent) participate directly in photography, painting, drawing, sculpting, dance (other than ballet), creative writing or classical music. If art experiences are so beneficial, why aren&#x27;t more people participating?</p><p>To help researchers shed light on this question, the RAND Corporation, a nonprofit institution that helps improve policy and decision-making through objective research and analysis, developed &quot;A Behavior Model of the Participant Decision&quot;, which can be used to investigate people&#x27;s inclinations about participating in an art activity (Yoshitomi 2000). According to Yoshitomi, each person has a disposition related to his or her interest in engaging in an art activity; a person&#x27;s disposition is based on sociodemographic characteristics, social or cultural identity, personality and previous experience. The RAND model clusters participants into three groups according to their disposition toward art participation: those disinclined to participate; those inclined to participate; and those currently participating.</p><p>The RAND findings reveal that the disinclined perceive themselves as being uncomfortable or unfamiliar with art. This disposition might occur among people who do not value art and who have not received art education, or who perceive themselves as unsophisticated or lacking skill to participate. The inclined are interested in participating, but may be constrained by particular barriers such as cost, time, and proper attire. Current participants are those who are involved, and influence or encourage others to participate. Researchers suggest that a strong relationship exists between childhood and adult art participation rates. Individuals with a greater number of childhood art experiences are more likely to have higher rates of participation as adults. Although 90 percent of Americans believe art instruction is important for children and should be offered in schools, almost 40 percent of schools either offer no art instruction or have art instructors with no formal art training.</p><p>One recreation organization working to make sure children get exposed to art is the Boys and Girls Clubs of America, which offer two innovative programs: The National Photography Program and the National Fine Arts Exhibit. Both are designed to get children excited about art. The photography program promotes new art that is technologically produced, including video and computer graphics, but primarily focuses on photography. The program provides club members with the opportunity to achieve personal growth and receive artistic recognition through instruction in photography. Participants also display their work at local, regional and national photography contests. The second program is the Fine Arts Exhibit. This encourages artistic expression, creativity, cultural appreciation and the development of artistic skills through classes, special events, exhibits and competitions. It allows participants to explore a variety of mediums, including drawing, painting, print making, collage and sculpture.</p><p>Because art experiences provide so many important benefits to individuals and communities, it is important for community programs to facilitate opportunities and provide encouragement to increase participation in a variety of programs.</p>", "3": "<p><b>A</b> For the casual viewer, the exhibition of landscapes, Australia, selected by the Royal Academy of Art will be a spectacular guide through Australian art history. Included in the exhibition are a range of artists and styles, dating from the earliest days of colonial art and progressing through expressionism and modernism to the artists of the 20th century, culminating with the current generation of Australian artists. It is hardly surprising, then, that this results in a flexible, wide-ranging notion of landscape.</p><p><b>B</b> But this landmark exhibition gives rise to some questions, and perhaps problems, regarding Britain’s relationship with its former colony. By choosing a style of painting at which British artists excel, the Academy could be seen as inviting criticism that hints at a telling attitude towards art by comparison. But it is the very theme of landscape painting that makes this a controversial selection. To consider if condescending is perhaps too strong, but for Joanna Mendelssohn, Australian critic and Associate Professor at the University of NSW’s College of Fine Arts (COFA), there is a suggestion that British artistic values have directed this exhibition, rather than allowing Australia the freedom to demonstrate its maturity.</p><p><b>C</b> What Mendelssohn found surprising about the exhibition was the underlying rules for the selection of works seemed to have been so conservative. Since the landscape is a very strong British artistic theme, it appeared to her that when the British looked to the art of a former colony, there was a tendency for them to think that those colonies would continue to be like the British themselves. In reviewing Australian art, the British insisted on looking at the genre of landscape painting.</p><p><b>D</b> Because of colonial ties, it was inevitable during Australian art’s formative years that it would reflect Britain’s devotion to the beloved landscape before its own character and idiosyncrasies took shape. And while Mendelssohn’s concern over the exhibition’s conventional selection is valid, the Academy is nevertheless embracing the peculiarities of Australian art from the mid-19th century onward, albeit within the boundaries of landscape.</p><p><b>E </b>Australia is curated by Kathleen Soriano, director of exhibitions at the Royal Academy. ‘Certainly the influence of English, French or German art is much more evident in the early periods, in the early 1800s to mid-1800s,’ she says. ‘What I wanted to show was how Australian art develops a real distinctiveness, associated with the landscape and the light.’</p><p><b>F </b>The fusion of ‘tradition’ of the European kind with something more specifically Australian, and often personal, is crucial to the exhibition and extends particularly to some of the more contemporary artists involved. Sydney-born video artist Shaun Gladwell is a good example of this. Gladwell’s most famous piece, which is featured in the exhibition, is Storm Sequence (2000), a video of Gladwell skateboarding on the Bondi seafront as one of Sydney’s signature brutal storms lingers offshore. It is his acknowledgment of landscape (or seascape) tradition, coloured by Gladwell’s own individualism. ‘To exhibit my work in this show might make some sense because I was interested in Turner and the idea of atmosphere affecting vision, something I was really interested in around the time of Storm Sequence. I was thinking about this tradition of Romantic landscape, but I wanted to make it personal,’ says Gladwell. But he didn’t want to just embark on borrowing imagery from elsewhere. He wanted to bring it to his experience and his world through skateboarding and beach culture.</p><p><b>G</b> So while it may seem narrow for Britain to reduce Australian art to the genre of landscape, there can be little denying that British landscape painting is still relevant to a current generation of Australian practitioners, however indirectly.</p><p><b>H</b> Visitors to the exhibition encounter Australian Aboriginal art first, the idea being that these works warrant a prominent position because they were ‘first’. Over the last couple of decades, London has hosted many successful exhibitions of Aboriginal art in smaller spaces, but for Soriano, Australia represents an opportunity to place such art within the context of new relationships to the art of the settlers and white Australia. ‘One of the reasons landscape was seen as being the right theme was because Australian art started in and on the landscape,’ she says. ‘[The exhibition] is a beautiful meshing of the two different kinds of art that allowed me to bring them together comfortably and honestly with this theme. It was important for me to present Indigenous art to audiences, and I felt it was most accurate to be seen as part of Australian art history, rather than a separate exhibition of its own.’</p><p><b>I</b> Meanwhile, Australian critic Mendelssohn also points out that London is increasingly less important to today’s generation of artists, and this somewhat weakens the ceremony surrounding the exhibition in London. ‘China is the most important art market in the world,’ she says. ‘If you’ve made it in Shanghai, you’ve made it. The world has changed. My students in Australia, who come from all over the world, really want to see Venice Biennale and Art Basel, but they’re less interested in going to London. When I was growing up, London was the destination, and then when I was at university all the smart young things wanted to go to New York,’ she added. ‘Now they want to go everywhere. There’s no such thing as the centre and the periphery like there used to be. It’s much more complicated.’</p>"}, "questionSegments": {"1": ["r1-p2"], "2": ["r1-p4"], "3": ["r1-p5"], "4": ["r1-p6"], "5": ["r1-p8"], "6": ["r1-p9"], "7": ["r1-p10"], "8": ["r1-p5"], "9": ["r1-p5"], "10": ["r1-p6"], "11": ["r1-p8"], "12": ["r1-p8"], "13": ["r1-p9"], "14": ["r2-p2"], "15": ["r2-p3"], "16": ["r2-p5"], "17": ["r2-p6"], "18": ["r2-p8"], "19": ["r2-p9"], "20": ["r2-p4"], "21": ["r2-p3"], "22": ["r2-p3"], "23": ["r2-p2"], "24": ["r2-p8"], "25": ["r2-p8"], "26": ["r2-p9"], "27": ["r3-p1"], "28": ["r3-p2"], "29": ["r3-p4"], "30": ["r3-p5"], "31": ["r3-p7"], "32": ["r3-p2"], "33": ["r3-p3"], "34": ["r3-p6"], "35": ["r3-p8"], "36": ["r3-p9"], "37": ["r3-p4"], "38": ["r3-p5"], "39": ["r3-p6"], "40": ["r3-p8"]}, "headingsBySection": {"2": [{"value": "i", "text": "Interpreting the research behind who is participating in art activities"}, {"value": "ii", "text": "How sales of artwork have increased in many countries"}, {"value": "iii", "text": "Two opportunities for getting kids involved in art activities"}, {"value": "iv", "text": "How art can be made accessible to the public"}, {"value": "v", "text": "Developing a model to explain the lack of participation in art"}, {"value": "vi", "text": "The connection between art and media"}, {"value": "vii", "text": "How involvement with art affects well-being and attitudes"}, {"value": "viii", "text": "How art makes communities safer and more vital"}]}, "grading": {"pairs": [], "sets": []}, "groups": [[1, 13], [14, 26], [27, 40]], "questionTypes": {"1": "boolean", "2": "boolean", "3": "boolean", "4": "boolean", "5": "boolean", "6": "boolean", "7": "boolean", "8": "gap", "9": "gap", "10": "gap", "11": "gap", "12": "gap", "13": "gap", "14": "heading", "15": "heading", "16": "heading", "17": "heading", "18": "heading", "19": "heading", "20": "matching", "21": "matching", "22": "matching", "23": "matching", "24": "gap", "25": "gap", "26": "gap", "27": "boolean", "28": "boolean", "29": "boolean", "30": "boolean", "31": "boolean", "32": "single", "33": "single", "34": "single", "35": "single", "36": "single", "37": "matching", "38": "matching", "39": "matching", "40": "matching"}, "sourceAnswerKey": {"1": ["NOT GIVEN"], "2": ["FALSE"], "3": ["NOT GIVEN"], "4": ["TRUE"], "5": ["FALSE"], "6": ["NOT GIVEN"], "7": ["TRUE"], "8": ["computers"], "9": ["space"], "10": ["dentures"], "11": ["toothpaste"], "12": ["toothbrushes"], "13": ["mouthguards"], "14": ["vii"], "15": ["viii"], "16": ["iv"], "17": ["v"], "18": ["i"], "19": ["iii"], "20": ["A"], "21": ["D"], "22": ["C"], "23": ["B"], "24": ["attire"], "25": ["rates"], "26": ["recognition"], "27": ["NO"], "28": ["NOT GIVEN"], "29": ["YES"], "30": ["YES"], "31": ["NO"], "32": ["C"], "33": ["B"], "34": ["A"], "35": ["C"], "36": ["A"], "37": ["F"], "38": ["E"], "39": ["A"], "40": ["C"]}, "sourceNotes": [], "hasAnswerKey": true};
